sp_widget.client_script:
api.controller = function(DHManagerService, $scope) {

    var c = this;

    $scope.$watch(() => DHManagerService.state.assetsLoading, (loading) => c.loading = loading);

    c.$onInit = function() {
        c.selectedAsset = DHManagerService.state.selectedAsset;

        if (c.selectedAsset) {
            c.metrics = DHManagerService.getSelectedAssetInfo()?.metrics?.filter((metric) => metric.category === 'Performance');
            console.log(c.metrics);
        }

        // Watch for changes in DHManagerService.selectedAsset
        $scope.$watch(() => DHManagerService.state.selectedAsset, function(newVal, oldVal) {

            if (newVal !== oldVal) {
                c.selectedAsset = newVal;

                if (c.selectedAsset) {
                    c.metrics = DHManagerService.getSelectedAssetInfo()?.metrics?.filter((metric) => metric.category === 'Performance');
                } else {
                    c.metrics = null;
                }
            }
        });
    }
};

sp_widget.css:
.error-display {
    display: flex;
    flex-direction: column;
    justify-items: center;
    align-items: center;
    font-size: large;
    font-weight: bold;
    gap: 20px;

    img {
        max-width: 450px;
        max-height: 150px;
    }
}

.loading {
    min-height: 15rem;
    width: 100%;
    border-radius: 1rem;
    background: #f6f7f8;
    background-image: linear-gradient(to right, #f6f7f8 0%, #edeef1 20%, #f6f7f8 40%, #f6f7f8 100%);
    background-repeat: no-repeat;
    background-size: 100rem 28rem;
    animation: shimmer 2s infinite linear;
  }

.metric {
    display: flex;
    justify-content: space-between;
    align-items:center;
    padding: 0 1rem;
    border-radius: 1rem;

    &:hover {
        background-color: rgba(128, 128, 128, .1);
    }

    .title {
        font-size: large;
        font-weight: bold;
    }

    .tooltip {
        text-transform: capitalize;
    }

    .rating {
        text-transform: capitalize;
        padding: 8px;
        border-radius: 10px;

        &.margin-sm {
            margin: .5rem 0;
        }

        svg {
            margin-top: .5rem;
            scale: 150%
        }

        &.poor {
            background-color: #FEE2E2;
            color: #DC2626;
        }

        &.average {
            background-color: #FEF3C7;
            color: #D97706;
        }

        &.good {
            background-color: #DCFCE7;
            color: #16A34A;
        }
    }
}
